schema_ddl:
CREATE TABLE clienti (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    email TEXT UNIQUE,
    telefono TEXT,
    data_registrazione DATE DEFAULT CURRENT_DATE
);

CREATE TABLE prodotti (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    prezzo NUMERIC(10,2) CHECK (prezzo >= 0),
    quantita_disponibile INT CHECK (quantita_disponibile >= 0)
);

CREATE TABLE ordini (
    id SERIAL PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    data_ordine DATE NOT NULL DEFAULT CURRENT_DATE,
    stato TEXT NOT NULL DEFAULT 'in attesa' CHECK (stato IN ('in attesa','spedito','consegnato','annullato'))
);

CREATE TABLE dettagli_ordine (
    id SERIAL PRIMARY KEY,
    ordine_id INT NOT NULL REFERENCES ordini(id),
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    quantita INT NOT NULL CHECK (quantita > 0),
    prezzo_unitario NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario >= 0)
);
